nasal.load:

var nodeName = cmdarg().getPath();

print("Loading Izumo ", cmdarg().getPath());

if ( bombable.check_overall_initialized (nodeName) ) {
  return;
}

var object_init = func() {
  thisNodeName = cmdarg().getPath();

  var bombableObject = {

    objectNodeName : thisNodeName,
    objectNode     : props.globals.getNode(thisNodeName),
    updateTime_s   : 1/3,
    altitudes : {
      wheelsOnGroundAGL_m : 0,
      minimumAGL_m        : 0,
      maximumAGL_m        : 0,
      crashedAGL_m        : -2,
    },
    velocities : {
      maxSpeedReduce_percent                       : 0.5,
      minSpeed_kt                                  : 0,
      cruiseSpeed_kt                               : 25,
      attackSpeed_kt                               : 30,
      maxSpeed_kt                                  : 33,
      damagedAltitudeChangeMaxRate_meterspersecond : 0.51,

      diveTerminalVelocities: {
        point1: { airspeed_kt : 447, vertical_speed_fps : - 74.4},
        point2: { airspeed_kt : 498, vertical_speed_fps : - 167.1},
        point3: { airspeed_kt : 535, vertical_speed_fps : - 255.0},
        point4: { airspeed_kt : 556, vertical_speed_fps : - 343.9},
      },
      climbTerminalVelocities: {
        point1: { airspeed_kt : 331.2, vertical_speed_fps : 34.3},
        point2: { airspeed_kt : 266.7, vertical_speed_fps : 59.4},
        point3: { airspeed_kt : 169.7, vertical_speed_fps : 73.1},
      },
    },
    evasions : {
      dodgeDelayMax_sec             : 60,
      dodgeDelayMin_sec             : 30,
      dodgeMax_deg                  : 0,
      dodgeMin_deg                  : 0,
      rollRateMax_degpersec         : 0,
      dodgeROverLPreference_percent : 50,
      dodgeAltMin_m                 : 0,
      dodgeAltMax_m                 : 0,
      dodgeVertSpeedClimb_mps       : 0,
      dodgeVertSpeedDive_mps        : 0,
    },
    attacks : {
      maxDistance_m              : 14000,
      minDistance_m              : 2500,
      continueAttackAngle_deg    : 0,
      altitudeHigherCutoff_m     : 15000,
      altitudeLowerCutoff_m      : 5000,
      climbPower                 : 0,
      divePower                  : 0,
      rollMin_deg                : 0,
      rollMax_deg                : 0,
      rollRateMax_degpersec      : 0,
      attackCheckTime_sec        : 10,
      attackCheckTimeEngaged_sec : 0.7,
    },
    weapons : {
      left_gun : {
        name                : "cannon",
        maxDamage_percent   : 0,
        maxDamageDistance_m : 700,
        weaponAngle_deg     : { heading: 240, elevation: -50 },
        weaponOffset_m      : { x:1, y:-2, z:0 },
        weaponSize_m        : { start:0.15, end:0.15 },
      },
    },
    dimensions : {
      width_m             : 39,
      length_m            : 249,
      height_m            : 50,
      damageRadius_m      : 120,
      vitalDamageRadius_m : 40,
      crashRadius_m       : 20,
    },
    vulnerabilities : {
      damageVulnerability               : 2,
      engineDamageVulnerability_percent : 20,
      fireVulnerability_percent         : 65,
      fireDamageRate_percentpersecond   : 0.03,
      fireExtinguishMaxTime_seconds     : 80,
      fireExtinguishSuccess_percentage  : 65,
      explosiveMass_kg                  : 3500000,
    },
    damageLiveries : {
      damageLivery : [  ]
    },
  };
  bombable.initialize ( bombableObject );
  # bombable.location_init ( thisNodeName );
  bombable.ground_init ( thisNodeName );
  bombable.attack_init ( thisNodeName );
  bombable.weapons_init ( thisNodeName );
  bombable.bombable_init ( thisNodeName );
  bombable.startSmoke("jetcontrail", thisNodeName );
}
object_init();

# ========== Model init (from Izumo.xml) ==========

var self = cmdarg();
print("Model load Izumo ", self.getPath());
var pathc = self.getPath();

# timescales

var elevator_transit_time = 30.0;
var jbd_transit_time = 0.5;

# register the dialog

setprop(pathc~"/dlg-name", "Izumo");

# init course control, animation and detail properties

setprop("/controls/Izumo/deck-park", 0);
setprop("/controls/Izumo/crew", 0);
setprop("/controls/Izumo/lights", 0);

setprop("/controls/Izumo/turn-to-launch-hdg", 0);
setprop("/controls/Izumo/turn-to-recovery-hdg", 0);
setprop("/controls/Izumo/turn-to-base-course", 1);

################
#  elevators

setprop("/controls/Izumo/elevator[0]/state", 1);
setprop("/controls/Izumo/elevator[1]/state", 0);

var elevator1 = aircraft.door.new(pathc~"/surface-positions/elevator[0]", elevator_transit_time, 1);
var elevator2 = aircraft.door.new(pathc~"/surface-positions/elevator[1]", elevator_transit_time, 0);

var elevator_array = [elevator1, elevator2];

################
# jet blast deflectors

setprop("/controls/Izumo/jbd[0]/state", 0);
setprop("/controls/Izumo/jbd[1]/state", 0);
setprop("/controls/Izumo/jbd[2]/state", 0);
setprop("/controls/Izumo/jbd[3]/state", 0);
setprop("/controls/Izumo/jbd[4]/state", 0);

var jbd1 = aircraft.door.new(pathc~"/surface-positions/jbd[0]", jbd_transit_time, 0);
var jbd2 = aircraft.door.new(pathc~"/surface-positions/jbd[1]", jbd_transit_time, 0);
var jbd3 = aircraft.door.new(pathc~"/surface-positions/jbd[2]", jbd_transit_time, 0);
var jbd4 = aircraft.door.new(pathc~"/surface-positions/jbd[3]", jbd_transit_time, 0);
var jbd5 = aircraft.door.new(pathc~"/surface-positions/jbd[4]", jbd_transit_time, 0);
var jbd_array = [jbd1, jbd2, jbd3, jbd4, jbd5];

# elevator control

var elevator_operate = func (i) {
  var tgt = getprop("/controls/Izumo/elevator["~i~"]/state");
  if (tgt == 1) {
    print ("Elevator ", i+1, " up.");
    elevator_array[i].open();
  } else {
    print ("Elevator ", i+1, " down.");
    elevator_array[i].close();
  }
}

# JBD control

var jbd_operate = func (i) {
  var tgt = getprop("/controls/Izumo/jbd["~i~"]/state");
  if (tgt == 1) {
    print ("JBD ", i+1, " up.");
    jbd_array[i].open();
  } else {
    print ("JBD ", i+1, " down.");
    jbd_array[i].close();
  }
}

# lighting control

var toggle_lights = func {
  var state = getprop(pathc~"/controls/lighting/deck-lights");
  if (state == 0) {
    setprop(pathc~"/controls/lighting/deck-lights", 1);
    setprop(pathc~"/controls/lighting/flood-lights-red-norm", 0.7);
  } else {
    setprop(pathc~"/controls/lighting/deck-lights", 0);
    setprop(pathc~"/controls/lighting/flood-lights-red-norm", 0.0);
  }
}

fn_an_spn_46 = getprop("/sim/fg-root") ~ "/Aircraft/Generic/an_spn_46.nas";
io.load_nasal(fn_an_spn_46, "an_spn_46");
var anspn = an_spn_46.ANSPN46_System.new("Izumo", self);
anspn.SetChannel(2);
var an_spn_46_timer = maketimer(6, func {
    anspn.Update();
    an_spn_46_timer.restart(anspn.GetUpdateRate());
});
an_spn_46_timer.restart(6);

# listeners

var l_elev1 = setlistener("/controls/Izumo/elevator/state", func {elevator_operate(0);},0,0);
var l_elev2 = setlistener("/controls/Izumo/elevator[1]/state", func {elevator_operate(1);},0,0);

var l_jbd1 = setlistener("/controls/Izumo/jbd[0]/state", func {jbd_operate(0);},0,0);
var l_jbd2 = setlistener("/controls/Izumo/jbd[1]/state", func {jbd_operate(1);},0,0);
var l_jbd3 = setlistener("/controls/Izumo/jbd[2]/state", func {jbd_operate(2);},0,0);
var l_jbd4 = setlistener("/controls/Izumo/jbd[3]/state", func {jbd_operate(3);},0,0);
var l_jbd5 = setlistener("/controls/Izumo/jbd[4]/state", func {jbd_operate(4);},0,0);

var l_lights = setlistener("/controls/Izumo/lights", func {toggle_lights();},0,0);

nasal.unload:

print("Unload Izumo.");
var nodeName= cmdarg().getPath();
bombable.de_overall_initialize( nodeName );
bombable.initialize_del( nodeName );
bombable.ground_del( nodeName );
bombable.location_del (nodeName);
bombable.bombable_del( nodeName );
bombable.attack_del( nodeName );
bombable.weapons_del (nodeName);

an_spn_46_timer.stop();

# clean up listeners

removelistener(l_elev1);
removelistener(l_elev2);

removelistener(l_jbd1);
removelistener(l_jbd2);
removelistener(l_jbd3);
removelistener(l_jbd4);
removelistener(l_jbd5);

removelistener(l_lights);
